async fn fetch_directive(
    database_url: &str,
    tenant_id: &str,
    repository_id: &str,
    directive_id: &str,
) -> AgentDirective {
    let client = raw_client(database_url).await;
    let row = client
        .query_one(
            "SELECT directive_payload FROM agent_directives \
             WHERE tenant_id = $1 AND repository_id = $2 AND directive_id = $3",
            &[&tenant_id, &repository_id, &directive_id],
        )
        .await
        .expect("the issued directive row should exist");
    let payload: Vec<u8> = row.get("directive_payload");
    AgentDirective::decode(payload.as_slice()).expect("the stored directive should decode")
}

/// `WorkCommandServiceOutcome::Executed.command` is the pre-execution
/// snapshot `confirm` looked up before running the effect (mirroring every
/// other kind, where the returned `command` is immutable request metadata,
/// not the mutable outcome); `directive_id` is written to the row DURING
/// execution, so a caller that wants it back reads the row again, same as
/// this test does.
async fn fetch_command_directive_id(
    database_url: &str,
    tenant_id: &str,
    repository_id: &str,
    command_id: &str,
) -> Option<String> {
    let client = raw_client(database_url).await;
    let row = client
        .query_one(
            "SELECT directive_id FROM work_commands \
             WHERE tenant_id = $1 AND repository_id = $2 AND command_id = $3",
            &[&tenant_id, &repository_id, &command_id],
        )
        .await
        .expect("the command row should exist");
    row.get("directive_id")
}

fn rfc3339(value: SystemTime) -> String {
    crate::wire_format::rfc3339(value).expect("test timestamps are representable as RFC3339")
}

fn applied_receipt(directive: &AgentDirective, occurred_at: SystemTime) -> v1::DirectiveReceipt {
    v1::DirectiveReceipt {
        directive_id: directive.directive_id.clone(),
        tenant_id: directive.tenant_id.clone(),
        project_id: directive.project_id.clone(),
        repository_id: directive.repository_id.clone(),
        node_id: directive.target_node_id.clone(),
        agent_session_id: directive.target_agent_session_id.clone(),
        status: v1::DirectiveReceiptStatus::Applied as i32,
        reason: v1::DirectiveReceiptReason::None as i32,
        occurred_at: rfc3339(occurred_at),
        payload_digest: directive.payload_digest.clone(),
        checkpoint_refs: Vec::new(),
        evidence_refs: vec!["evidence:checkpoint".to_owned()],
        directive_sequence: directive.sequence,
        diagnostic: String::new(),
        outbox_sequence: None,
    }
}

#[tokio::test]
async fn confirming_pause_issues_a_matching_directive_without_moving_the_task() {
    let Some(database_url) = database_url() else {
        eprintln!("skipping: ACKPLANE_TEST_DATABASE_URL is not set");
        return;
    };
    let fixture = fixture(&database_url, vec![SupervisorDirectiveCapability::Pause]).await;
    let now = SystemTime::now();
    let (command, payload) = pause_command(&fixture, now);
    let authorization = authorization_for(&fixture, vec![WorkCommandKind::Pause]);

    let mut service = WorkCommandService::connect(&database_url)
        .await
        .expect("the command service should connect");
    let submitted = service
        .submit(authorization.clone(), command, now)
        .await
        .expect("submission should record a pending confirmation");
    let super::service::WorkCommandServiceOutcome::PendingConfirmation { command, .. } = submitted
    else {
        panic!("submission must enter pending confirmation");
    };

    let executed = service
        .confirm(
            authorization,
            &fixture.tenant_id,
            &fixture.repository_id,
            &command.command_id,
            payload,
            now,
        )
        .await
        .expect("confirming should issue the directive");
    let super::service::WorkCommandServiceOutcome::Executed {
        command, receipt, ..
    } = executed
    else {
        panic!("confirming a recorded command must execute");
    };

    // Acceptance point 2: the immediate receipt is PendingDelivery, never a
    // claim that the worker actually paused.
    assert_eq!(receipt.outcome, WorkCommandOutcome::PendingDelivery);

    let directive_id = fetch_command_directive_id(
        &database_url,
        &fixture.tenant_id,
        &fixture.repository_id,
        &command.command_id,
    )
    .await
    .expect("directive_id set");
    let directive = fetch_directive(
        &database_url,
        &fixture.tenant_id,
        &fixture.repository_id,
        &directive_id,
    )
    .await;
    assert_eq!(directive.target_node_id, fixture.node_id);
    assert_eq!(directive.target_agent_session_id, fixture.session_id);
    assert_eq!(directive.kind, v1::DirectiveKind::Pause as i32);
    assert_eq!(directive.required_capability, "pause.v1");

    // Acceptance point 2 (continued): work_tasks itself has not moved yet.
    let work_store = WorkStore::connect(&database_url)
        .await
        .expect("connect work store");
    let detail = work_store
        .task_detail(&fixture.tenant_id, &fixture.repository_id, &fixture.task_id)
        .await
        .expect("reading the task back should succeed")
        .expect("the task should exist");
    assert_eq!(detail.task.state, crate::work_store::WorkTaskState::Open);
}

